import type { Registry } from "./compile.ts";

/** TypeScript source with the identifier unions of the specification. Committed; a test checks it is current. */
export function generatedSource(r: Registry): string {
  const union = (name: string, ids: string[]) =>
    `export const ${name}s = ${JSON.stringify(ids.sort(), null, 2)} as const;\nexport type ${name} = (typeof ${name}s)[number];\n`;
  return [
    "// Generated by `pnpm spec:build` from docs/spec. Do not edit.",
    "",
    union("ServiceId", Object.keys(r.services)),
    union("MechanismId", Object.keys(r.mechanisms)),
    union("RuleId", Object.keys(r.rules)),
  ].join("\n");
}
